        "Voter key-binding (2026-09-15 ruling ⑤): after owner-0001 "
        "votes with its old key on the dev-dedicated admin's proposal "
        "25 (seq 26), owner-0001 is removed via proposal (seq 27 → 28) "
        "and re-added as owner with **different keys** (seq 29 → 30). "
        "owner-0014's approve at seq 31 recounts the (0001, old-key) "
        "vote by 'is it a current owner holding this key FP now', "
